function error(loc, kind) {
    return h.object([["loc", loc], ["type", kind]]);
}

function string_field(errors, input, name, minimum, maximum) {
    let value;
    if (h.truth(h.not_in(name, input))) {
        h.append(errors, error([name], "missing"));
        return "";
    }
    value = h.get(input, name);
    if (h.truth(h.not(h.is_string(value)))) {
        h.append(errors, error([name], "string_type"));
        return "";
    }
    if (h.truth(h.lt(h.len(value), minimum))) {
        h.append(errors, error([name], "string_too_short"));
    } else {
        if (h.truth((h.truth(h.ne(maximum, null)) ? h.gt(h.len(value), maximum) : h.ne(maximum, null)))) {
            h.append(errors, error([name], "string_too_long"));
        }
    }
    return value;
}

function integer_field(errors, input, name, minimum, maximum, v_default, strict) {
    let kind, value;
    if (h.truth((h.truth(h.not_in(name, input)) ? h.eq(v_default, null) : h.not_in(name, input)))) {
        h.append(errors, error([name], "missing"));
        return 0;
    }
    value = h.get(input, name, v_default);
    if (h.truth((h.truth(strict) ? h.not(h.is_integer(value)) : strict))) {
        h.append(errors, error([name], "int_type"));
        return 0;
    }
    if (h.truth((h.truth(h.not(h.is_integer(value))) ? (h.truth(h.ne(value, true)) ? h.ne(value, false) : h.ne(value, true)) : h.not(h.is_integer(value))))) {
        if (h.truth((h.truth(h.is_string(value)) ? h.regex("^[+-]?[0-9]+([.]0+)?$", h.strip(value)) : h.is_string(value)))) {
            value = h.int(h.float(value));
        } else {
            kind = (h.truth(h.is_string(value)) ? "int_parsing" : (h.truth(h.is_number(value)) ? "int_from_float" : "int_type"));
            h.append(errors, error([name], kind));
            return 0;
        }
    }
    value = h.int(value);
    if (h.truth((h.truth(h.ne(minimum, null)) ? h.lt(value, minimum) : h.ne(minimum, null)))) {
        h.append(errors, error([name], "greater_than_equal"));
    } else {
        if (h.truth((h.truth(h.ne(maximum, null)) ? h.gt(value, maximum) : h.ne(maximum, null)))) {
            h.append(errors, error([name], "less_than_equal"));
        }
    }
    return value;
}

function forbid_extra(errors, input, allowed) {
    let key;
    const seq_1 = h.keys(input);
    for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {
        key = seq_1[index_1];
        if (h.truth(h.not_in(key, allowed))) {
            h.append(errors, error([key], "extra_forbidden"));
        }
    }
    return null;
}

function outcome(errors, value) {
    return (h.truth(errors) ? h.object([["ok", false], ["errors", errors]]) : h.object([["ok", true], ["value", value]]));
}

function response(status, value) {
    return h.object([["status", status], ["json", value]]);
}

function route(request, path, method) {
    if (h.truth(h.ne(h.url_path(h.get(request, "url", "/")), path))) {
        return response(404, h.object([["detail", "Not Found"]]));
    }
    if (h.truth(h.ne(h.get(request, "method", "GET"), method))) {
        return response(405, h.object([["detail", "Method Not Allowed"]]));
    }
    return null;
}

function request_headers(request) {
    let key, out, values;
    out = h.object([]);
    values = h.get(request, "headers", h.object([]));
    const seq_2 = h.keys(values);
    for (let index_2 = 0; index_2 < seq_2.length; ++index_2) {
        key = seq_2[index_2];
        h.set(out, h.lower(key), h.get(values, key));
    }
    return out;
}

function body_errors(errors) {
    let item, out;
    out = [];
    const seq_3 = errors;
    for (let index_3 = 0; index_3 < seq_3.length; ++index_3) {
        item = seq_3[index_3];
        h.append(out, error(h.add(["body"], h.get(item, "loc")), h.get(item, "type")));
    }
    return h.object([["status", 422], ["errors", out]]);
}

export function solve(input) {
    let failure, out, request;
    out = [];
    const seq_4 = h.get(input, "requests");
    for (let index_4 = 0; index_4 < seq_4.length; ++index_4) {
        request = seq_4[index_4];
        failure = route(request, "/v1/private", "GET");
        if (h.truth(failure)) {
            h.append(out, failure);
        } else {
            if (h.truth(h.ne(h.get(request_headers(request), "x-api-key"), "academy"))) {
                h.append(out, response(401, h.object([["detail", "Invalid API key"]])));
            } else {
                h.append(out, response(200, h.object([["actor", "plugin"]])));
            }
        }
    }
    return out;
}
