export function solve(input) {
    let done, i, index, left, migration, parent, plan, ready;
    done = h.unique(h.get(input, "applied"));
    left = h.clone(h.get(input, "migrations"));
    plan = [];
    while (h.truth(left)) {
        index = h.neg(1);
        const seq_1 = h.range(h.len(left));
        for (let index_1 = 0; index_1 < seq_1.length; ++index_1) {
            i = seq_1[index_1];
            migration = h.get(left, i);
            ready = h.not_in(h.get(migration, "id"), done);
            const seq_2 = h.get(migration, "parents");
            for (let index_2 = 0; index_2 < seq_2.length; ++index_2) {
                parent = seq_2[index_2];
                ready = (h.truth(ready) ? h.in(parent, done) : ready);
            }
            if (h.truth(ready)) {
                index = i;
                break;
            }
        }
        if (h.truth(h.lt(index, 0))) {
            const seq_3 = left;
            for (let index_3 = 0; index_3 < seq_3.length; ++index_3) {
                migration = seq_3[index_3];
                if (h.truth(h.not_in(h.get(migration, "id"), done))) {
                    return null;
                }
            }
            return plan;
        }
        migration = h.pop(left, index);
        h.append(done, h.get(migration, "id"));
        h.append(plan, h.get(migration, "id"));
    }
    return plan;
}
